entries[351768] = { ["name"] = "Greater Drums of Speed", ["text"] = "15 sec cast\nReagents:\nHeavy Knothide Leather (6), Wind Scales (4)\nGreater Drums of Speed\n(0)\nRequires Leatherworking\n(340)\nUse: Increases movement speed of party members within 40 yards by 15%. Lasts 30 sec. Drums can be used while shapeshifted. (2 Min Cooldown)\n50 Charges" }
