entries[351770] = { ["name"] = "Greater Drums of Panic", ["text"] = "15 sec cast\nReagents:\nHeavy Knothide Leather (6), Fel Hide (4)\nGreater Drums of Panic\n(0)\nRequires Leatherworking\n(350)\nUse: Unearthly rhythms cause 5 enemies within 8 yds to flee in terror for 2 sec. Drums can be used while shapeshifted. (2 Min Cooldown)\n50 Charges" }
entries[351771] = { ["name"] = "Greater Drums of Battle", ["text"] = "15 sec cast\nReagents:\nHeavy Knothide Leather (6), Thick Clefthoof Leather (4)\nGreater Drums of Battle\n(0)\nRequires Leatherworking\n(350)\nUse: Increases haste rating on party members within 40 yards by 80. Lasts 30 sec. Drums can be used while shapeshifted. Cannot affect targets level 80 or higher. (2 Min Cooldown)\n50 Charges" }
